# Shared helpers for muelle-receive and muelle-worker.
# Expects MUELLE_CONFIG to point to the JSON config generated by the NixOS module.

die() {
  echo "muelle: $*" >&2
  exit 1
}

: "${MUELLE_CONFIG:?MUELLE_CONFIG not set}"

cfg() {
  jq -r "$1" "$MUELLE_CONFIG"
}

STATE_DIR=$(cfg .stateDir)
BASE_DIR=$(cfg .baseDir)
DOMAIN=$(cfg .domain)

# get FIELD from a JSON document held in a variable
jget() {
  jq -r --arg k "$2" '.[$k] // "" | tostring' <<<"$1"
}

valid() {
  # valid REGEX VALUE
  [[ $2 =~ $1 ]]
}

status_path() {
  printf '%s/status/%s.json' "$STATE_DIR" "$1"
}

# write_status ID STATE MESSAGE [URL] [META_JSON]
write_status() {
  local id=$1 state=$2 msg=$3 url=${4:-} meta=${5:-{}}
  local dest tmp
  dest=$(status_path "$id")
  tmp=$(mktemp "$STATE_DIR/status/.tmp.XXXXXX")
  jq -n \
    --arg id "$id" --arg state "$state" --arg message "$msg" --arg url "$url" \
    --argjson meta "$meta" \
    --arg updated "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    '({id: $id, state: $state, message: $message, url: $url, updated: $updated} + $meta)' >"$tmp"
  chmod 0644 "$tmp"
  mv -f "$tmp" "$dest"
}

# slot_for SITE ENV BRANCH SHA -> prod | next | <8 hex>
slot_for() {
  case $2 in
  prod | next) printf '%s' "$2" ;;
  preview) printf '%s\n%s\n%s' "$1" "$3" "$4" | sha256sum | cut -c1-8 ;;
  esac
}

# url_for SITE SLOT
url_for() {
  if [[ $2 == prod ]]; then
    jq -r --arg s "$1" '.sites[$s].prodUrl' "$MUELLE_CONFIG"
  else
    printf 'https://%s-%s.%s' "$2" "$1" "$DOMAIN"
  fi
}
